-- Nexmark qhopv on clink, BLACKHOLE sink variant. NOT a nexmark query. qhop's
-- windowed counts with the window start projected and a primary key, so
-- upsert_gate.sh compares the VALUES rather than the row count. This exists
-- because a window that fires early emits the same NUMBER of panes with lower
-- counts in them, so no row-count gate can see an undercount - which is the
-- failure mode a multi-partition watermark produces, and the one 34819d4
-- fixed once already. This is the check that would notice it coming back.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-qhopvbh-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4001');
CREATE TABLE sink_qhopv (wstart BIGINT, auction BIGINT, num BIGINT) WITH (connector='blackhole');
INSERT INTO sink_qhopv
SELECT window_start AS wstart, auction, COUNT(*) AS num FROM bid GROUP BY HOP(datetime, INTERVAL '10' SECOND, INTERVAL '2' SECOND), auction;
